  n = Z.of_nat (length src) ->
  (S + Z.of_nat (length (src ++ rest)) <= D \/ D + n <= S)%Z ->
  (D + n < 2^63)%Z -> (S + Z.of_nat (length (src ++ rest)) < 2^63)%Z -> (1 <= n)%Z ->
  rng RNG S n -> rng RNG D n ->
