End CANSEC2.
Ltac shr0 :=
  repeat match goal with |- context [Z.shiftr ?x ?k] =>
    replace (Z.shiftr x k) with 0%Z by (rewrite Z.shiftr_div_pow2 by lia; symmetry; apply Z.div_small; lia) end.


